 public class AudioWaveStrip:Control {
  readonly System.Collections.Generic.Queue<float> samples=new System.Collections.Generic.Queue<float>();
  public AudioWaveStrip(){DoubleBuffered=true;AccessibleName="Measured audio level";}
  public void Push(float peak){samples.Enqueue(Math.Max(0,Math.Min(1,peak)));while(samples.Count>120)samples.Dequeue();Invalidate();}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);float[] values=samples.ToArray();int count=Math.Max(1,Width/7);using(var brush=new SolidBrush(ForeColor)){for(int i=0;i<count;i++){int index=values.Length-count+i;float v=index>=0?values[index]:0;int h=Math.Max(2,(int)(v*(Height-4)));e.Graphics.FillRectangle(brush,i*7,(Height-h)/2,3,h);}}}
 }
 public sealed class LiquidNavRail:Panel {
  readonly System.Windows.Forms.Timer clock=new System.Windows.Forms.Timer{Interval=16};readonly Stopwatch elapsed=new Stopwatch();float from,to,current;int selected;bool moving;RectangleF cachedFrame,startFrame;
  public LiquidNavRail(){DoubleBuffered=true;clock.Tick+=(s,e)=>{float t=Math.Min(1,(float)elapsed.Elapsed.TotalMilliseconds/180);if(t>=1||!PageMotion.MotionAllowed()){current=to;moving=false;clock.Stop();}else{cachedFrame=FrameAt(startFrame,to,t,Width,ItemHeight);current=cachedFrame.Y;}Invalidate(true);};}
  static RectangleF FrameAt(RectangleF start,float end,float progress,int width,float itemHeight){float t=Math.Max(0,Math.Min(1,progress)),ease=PageMotion.Ease(t),pulse=(float)Math.Sin(Math.PI*t);pulse*=pulse;float full=Math.Max(itemHeight,width-2),baseWidth=start.Width+(full-start.Width)*ease,w=Math.Max(itemHeight,baseWidth-(full-itemHeight)*pulse);return new RectangleF((width-w)/2,start.Y+(end-start.Y)*ease,w,itemHeight);}
  public static RectangleF BoundsAt(float start,float end,float progress,int width,float itemHeight=46){return FrameAt(new RectangleF(1,start,Math.Max(itemHeight,width-2),itemHeight),end,progress,width,itemHeight);}
  float ItemHeight{get{return Controls.Count>0?Controls[0].Height:46;}}
  public RectangleF Indicator{get{return moving?cachedFrame:new RectangleF(1,current,Math.Max(1,Width-2),ItemHeight);}}
  public System.Drawing.Drawing2D.GraphicsPath IndicatorPath(float x=0,float y=0){var bounds=Indicator;float contraction=Math.Max(0,Math.Min(1,(Width-2-bounds.Width)/Math.Max(1,Width-2-bounds.Height))),radius=12+(bounds.Height/2-12)*contraction;bounds.Offset(x,y);return RoundedButton.Shape(bounds,Math.Min(radius,Math.Min(bounds.Height/2,bounds.Width/2)));}

  public void SelectIndex(int index){if(index<0||index>=Controls.Count)return;float target=Controls[index].Top;if(selected==index&&Math.Abs(current-target)<.1f)return;startFrame=Indicator;cachedFrame=startFrame;selected=index;from=current;to=target;if(!Visible||!PageMotion.MotionAllowed()){current=to;moving=false;clock.Stop();}else{moving=true;elapsed.Restart();clock.Start();}Invalidate(true);}
  protected override void OnLayout(LayoutEventArgs e){base.OnLayout(e);foreach(Control button in Controls)if(button.Width!=ClientSize.Width)button.Width=ClientSize.Width;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;using(var p=IndicatorPath())using(var b=new SolidBrush(Color.FromArgb(15,42,46)))e.Graphics.FillPath(b,p);}
  protected override void Dispose(bool disposing){if(disposing)clock.Dispose();base.Dispose(disposing);}
 }
